using UnityEngine;

namespace Astrea;

public class TurnManager : ReferenceSingleton<TurnManager>
{
	[Header("Turns Map")]
	[SerializeField]
	private PlayerTurn playerTurn;

	[SerializeField]
	private PlayerTurnTutorial playerTurnTutorial;

	[SerializeField]
	private EnemyTurn enemyTurn;

	[SerializeField]
	private DrawTurn drawTurn;

	[SerializeField]
	private EndOfAllTurn endOfAllTurn;

	[Header("Runtime")]
	[SerializeField]
	private int turnIndex;

	[SerializeField]
	private Turn[] turns;

	[SerializeField]
	private Turn currentTurn;

	[SerializeField]
	private Turn previousTurn;

	private bool ambushBattle;

	public PlayerTurn PlayerTurn => playerTurn;

	public PlayerTurnTutorial PlayerTurnTutorial => playerTurnTutorial;

	public EnemyTurn EnemyTurn => enemyTurn;

	public DrawTurn DrawTurn => drawTurn;

	public EndOfAllTurn EndOfAllTurn => endOfAllTurn;

	public Turn CurrentTurn => currentTurn;

	public bool AmbushBattle => ambushBattle;

	public void InitializeBattle(bool ambushBattle)
	{
		this.ambushBattle = ambushBattle;
	}

	public void SetPlayerTurnTutorial(PlayerTurn playerTurnTutorial)
	{
		playerTurn = playerTurnTutorial;
		turns[1] = playerTurnTutorial;
	}

	public void EndOfBattleInitialize()
	{
		ambushBattle = false;
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.EndTurnsBattle();
	}

	public void InitializeTurnsBattle()
	{
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.InitializeTurnsBattle();
	}

	public void InitializeTurn()
	{
		SetTurn(turns[0]);
	}

	public void StartNextTurn()
	{
		previousTurn = currentTurn;
		turnIndex++;
		if (turnIndex > turns.Length - 1)
		{
			turnIndex = 0;
		}
		SetTurn(turns[turnIndex]);
	}

	public void JumpNextTurn()
	{
		previousTurn = currentTurn;
		turnIndex += 2;
		if (turnIndex > turns.Length - 1)
		{
			turnIndex = 0;
		}
		SetTurn(turns[turnIndex]);
	}

	private void SetTurn(Turn turn)
	{
		if (currentTurn != null)
		{
			previousTurn = currentTurn;
			currentTurn.OnEndTurn();
		}
		for (int i = 0; i < turns.Length; i++)
		{
			if (turns[i] == turn)
			{
				turnIndex = i;
			}
		}
		currentTurn = turn;
		currentTurn.OnStartTurn();
	}

	public void StartNextTurnWithNoActivations()
	{
		previousTurn = currentTurn;
		turnIndex++;
		if (turnIndex > turns.Length - 1)
		{
			turnIndex = 0;
		}
		SetTurnWithNoActivations(turns[turnIndex]);
	}

	private void SetTurnWithNoActivations(Turn turn)
	{
		previousTurn = currentTurn;
		currentTurn = turn;
		currentTurn.SetTurnName();
	}
}
